import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link, useLocation } from 'react-router-dom';
import { 
  BarChart3, Map, TrendingUp, Shield, 
  Search, Plus, Menu, X, Globe, Bell
} from 'lucide-react';
import Button from './Button';
import { useAuth } from '../../contexts/AuthContext';
import { useTranslation } from '../../contexts/LanguageContext';

export const PremiumHeader = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { user } = useAuth();
  const { t, i18n } = useTranslation();
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Live Analytics', path: '/analytics-dashboard', icon: BarChart3 },
    { name: 'Issue Map', path: '/interactive-issue-map', icon: Map, badge: 'Real-time' },
    { name: 'AI Insights', path: '/analytics-dashboard', icon: TrendingUp, badge: 'New' },
    { name: 'Transparency', path: '/public-reports-listing', icon: Shield },
  ];

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
      isScrolled 
        ? 'bg-white/90 backdrop-blur-xl py-3 shadow-premium' 
        : 'bg-transparent py-6'
    }`}>
      <div className="container mx-auto px-6">
        <nav className="flex items-center justify-between">
          {/* Logo & Brand */}
          <Link to="/" className="flex items-center gap-3 group">
            <div className="w-10 h-10 bg-gradient-to-br from-[#2563eb] to-[#7c3aed] rounded-xl flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform">
              <Shield size={24} />
            </div>
            <div>
              <span className={`text-xl font-black tracking-tight block ${isScrolled ? 'text-neutral-900' : 'text-neutral-900'}`}>
                Civic Care
              </span>
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-neutral-400 block -mt-1">
                AI Intelligence
              </span>
            </div>
          </Link>

          {/* Center Navigation (Desktop) */}
          <div className="hidden lg:flex items-center gap-8">
            {navLinks.map((link) => (
              <Link 
                key={link.name} 
                to={link.path}
                className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-neutral-500 hover:text-primary-blue transition-colors relative group"
              >
                <link.icon size={14} className="group-hover:scale-110 transition-transform" />
                {link.name}
                {link.badge && (
                  <span className={`px-2 py-0.5 rounded-full text-[8px] ${
                    link.badge === 'New' ? 'bg-purple-100 text-purple-700' : 'bg-cyan-100 text-cyan-700'
                  }`}>
                    {link.badge}
                  </span>
                )}
              </Link>
            ))}
          </div>

          {/* Right Actions */}
          <div className="flex items-center gap-4">
             <div className="hidden md:flex items-center gap-2 mr-4 border-r border-neutral-100 pr-4">
                <button className="p-2 text-neutral-400 hover:text-primary-blue transition-colors">
                   <Globe size={18} />
                </button>
                <button className="p-2 text-neutral-400 hover:text-primary-blue transition-colors relative">
                   <Bell size={18} />
                   <div className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white" />
                </button>
             </div>

             <div className="hidden sm:flex items-center gap-3">
                <Link to="/login">
                  <Button variant="ghost" className="text-[10px] font-black uppercase tracking-widest">
                    Log In
                  </Button>
                </Link>
                <Link to="/issue-reporting-form">
                  <Button className="bg-[#2563eb] text-white px-6 h-12 rounded-xl font-black uppercase tracking-widest text-[10px] shadow-lg shadow-blue-900/20">
                    <Plus size={16} className="mr-1.5" /> Report Issue
                  </Button>
                </Link>
             </div>

             {/* Mobile Menu Toggle */}
             <button 
                className="lg:hidden p-2 text-neutral-900"
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
             >
                {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
             </button>
          </div>
        </nav>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="lg:hidden bg-white border-t border-neutral-100 overflow-hidden"
          >
            <div className="container mx-auto px-6 py-8 flex flex-col gap-6">
              {navLinks.map((link) => (
                <Link 
                  key={link.name} 
                  to={link.path}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="flex items-center gap-4 text-sm font-bold text-neutral-900"
                >
                  <div className="p-2 bg-neutral-50 rounded-lg">
                    <link.icon size={20} className="text-primary-blue" />
                  </div>
                  {link.name}
                </Link>
              ))}
              <hr className="border-neutral-100" />
              <div className="flex flex-col gap-4">
                 <Link to="/login" onClick={() => setIsMobileMenuOpen(false)}>
                    <Button variant="outline" className="w-full h-14 rounded-2xl font-bold">Log In</Button>
                 </Link>
                 <Link to="/issue-reporting-form" onClick={() => setIsMobileMenuOpen(false)}>
                    <Button className="w-full h-14 rounded-2xl bg-primary-blue text-white font-bold">Report Issue</Button>
                 </Link>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
};

export default PremiumHeader;
